#' G-computation (Parametric G-formula)
#'
#' Estimates the marginal (population-average) causal effect of a binary point 
#' treatment using the parametric g-formula (g-computation). An outcome model 
#' is fitted conditional on treatment and covariates; the fitted model then 
#' predicts each subject's outcome under treatment and under no treatment, and 
#' these predictions are averaged (standardized) over the covariate 
#' distribution to give the counterfactual means E(Y^1) and E(Y^0). The
#' average treatment effect is reported as a difference (and, for binary 
#' outcomes, a risk ratio), with percentile bootstrap confidence intervals. 
#' This standardization removes confounding by the measured covariates without 
#' requiring a propensity model.
#' 
#'
#' @examples
#' \donttest{
#' gcomputation(
#'     data = mydata,
#'     outcome = "death",
#'     treatment = "treated",
#'     covariates = vars(age, stage, grade),
#'     outcomeType = "binary")
#'}
#' @param data The data as a data frame (one row per subject).
#' @param outcome The outcome. Continuous, or a two-level factor / 0-1 numeric
#'   for binary.
#' @param outcomeType Whether the outcome is continuous (linear model) or
#'   binary (logistic model).
#' @param outcomeEvent For a binary factor outcome, the level treated as the
#'   event.
#' @param treatment The binary treatment / exposure variable.
#' @param treatmentLevel The level of the treatment variable representing
#'   "treated".
#' @param covariates Covariates to adjust for (measured confounders).
#' @param interactions Include treatment-by-covariate interactions in the
#'   outcome model, allowing effect modification. The marginal effect is still
#'   standardized over the covariate distribution.
#' @param bootstrap_n Number of bootstrap resamples for the confidence
#'   interval.
#' @param conf_level Confidence level for the bootstrap interval.
#' @param showCounterfactual Report the standardized counterfactual means
#'   E(Y^1) and E(Y^0).
#' @param showPlot Display the counterfactual means with the treatment effect.
#' @param showSummary Display a plain-language summary of the estimated
#'   effect.
#' @param showExplanation Display an explanation of the g-formula.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mainTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$counterfactualTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$mainTable$asDF}
#'
#' \code{as.data.frame(results$mainTable)}
#'
#' @export
gcomputation <- function(
    data,
    outcome,
    outcomeType = "continuous",
    outcomeEvent,
    treatment,
    treatmentLevel,
    covariates,
    interactions = FALSE,
    bootstrap_n = 1000,
    conf_level = 0.95,
    showCounterfactual = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("gcomputation requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(covariates)) covariates <- jmvcore::resolveQuo(jmvcore::enquo(covariates))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(covariates), covariates, NULL))


    options <- gcomputationOptions$new(
        outcome = outcome,
        outcomeType = outcomeType,
        outcomeEvent = outcomeEvent,
        treatment = treatment,
        treatmentLevel = treatmentLevel,
        covariates = covariates,
        interactions = interactions,
        bootstrap_n = bootstrap_n,
        conf_level = conf_level,
        showCounterfactual = showCounterfactual,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- gcomputationClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

